export interface Attachment {
  name: string;
  type: 'pdf' | 'doc' | 'image';
  size?: string;
}

export interface RequisitionItem {
  id: number;
  no: number;
  partName: string;
  spec: string;
  position: string;
  makerName: string;
  qty: number;
  unit: string;
  remark: string;
  poRef?: string;
  isUrgent: boolean;
  attachments?: Attachment[];
  // Detail for M/M
  machineModel: string;
  machineMaker: string;
  serialNo: string;
  // Detail for P/H (Procurement)
  // Quotation 1
  acCode: string;
  vendor: string;
  unitPrice: number | null;
  currency: string;
  crCode: string;
  quotationNo: string;
  quotationPdf?: string;
  leadTime: string;
  // Quotation 2
  acCode2?: string;
  vendor2?: string;
  unitPrice2?: number | null;
  currency2?: string;
  crCode2?: string;
  quotationNo2?: string;
  quotationPdf2?: string;
  leadTime2?: string;
  status: 'Waiting Quotation' | 'Quoted' | 'Approved' | 'PO Issued';
  isEditing?: boolean;
  backupData?: any;
}

export interface QuotationSearchResult {
  id: string;
  quotationNo: string;
  partName: string;
  spec: string;
  makerName: string;
  vendor: string;
  vendorRating?: number;
  unitPrice: number;
  originalPrice?: number;
  discountPercent?: number;
  currency: string;
  leadTime: string;
  status: 'Approved' | 'Quoted' | 'Waiting Quotation' | 'PO Issued';
  isUrgent: boolean;
  isMall?: boolean;
  location?: string;
  category?: string;
  soldCount?: string;
  voucherText?: string;
  stockCount?: number;
  partType?: 'cylinder' | 'vacuum' | 'linear' | 'sensor' | 'motor' | 'filter' | 'valve';
  docNumber: string;
  requesterName: string;
  division: string;
  section: string;
  quotationDate: string;
  quotationPdf?: string;
  machineModel?: string;
  descriptionSnippet: string;
  urlBreadcrumb: string;
  priceHistory?: Array<{ year: string; price: number; vendor: string }>;
  tags: string[];
  matchScore?: number;
  rank?: number;
}

